# Atualizacao da navegacao do catalogo IPTVPremium.
# Compativel com Windows PowerShell 5.1 e PowerShell 7.
# Execute no terminal PowerShell do Android Studio, na raiz do projeto.
[CmdletBinding()]
param([string]$Projeto = (Get-Location).Path)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Get-BytesHash([byte[]]$Bytes) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-', '') }
    finally { $sha.Dispose() }
}
function Get-TextHash([byte[]]$Bytes) {
    $text = [Text.Encoding]::UTF8.GetString($Bytes).TrimStart([char]0xFEFF).Replace("`r`n", "`n")
    return Get-BytesHash ([Text.Encoding]::UTF8.GetBytes($text))
}
$files = @(
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/components/CatalogGridNavigation.kt'; Before = '746E1CA7974F19CA20E5C7DB97BC3D5EE7D9C3F1C806B5B5DDF842E3A82232B9'; After = '7ADD8EC05BD1CE6A2DB8B0092579933BA9950BC6EA8BD1F07F2241BBE73D86D4'; PayloadHash = '7ADD8EC05BD1CE6A2DB8B0092579933BA9950BC6EA8BD1F07F2241BBE73D86D4'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MoviesScreen.kt'; Before = 'FC8D7BA9E8F0C778C4A6F5FB9E090ECAB05667535D0210E9F51F0250C7DCAD84'; After = 'AE55A8D73C0E5F169E8EFFD81061C2796EFFF253DF857544C8DB21D4801D59E8'; PayloadHash = 'AE55A8D73C0E5F169E8EFFD81061C2796EFFF253DF857544C8DB21D4801D59E8'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/series/SeriesScreen.kt'; Before = 'A664254F0EF3E724318D1FDFD6FBEEF11BC64DF4B0F0093CE0CC7575C8E942A3'; After = 'B03F0353F2937EF01E1FBE4A6423133653C25913EE43EF4D3FFC858049AC9CF4'; PayloadHash = 'B03F0353F2937EF01E1FBE4A6423133653C25913EE43EF4D3FFC858049AC9CF4'; Data = '' },
    @{ Path = 'app/src/androidTest/java/br/com/flaviotorres/iptvpremium/data/repository/CatalogNavigationDeviceTest.kt'; Before = '5EB56029B1768FD31D111118651AF44CB92E6DB23AB5961C83E0420442D90E1B'; After = '876923E6F7863A7AD38C940286C0F9B8E416BEBC4E84E7418CDCBD786E3FA8C5'; PayloadHash = '876923E6F7863A7AD38C940286C0F9B8E416BEBC4E84E7418CDCBD786E3FA8C5'; Data = '' }
)
$root = (Resolve-Path -LiteralPath $Projeto).Path
if (!(Test-Path -LiteralPath (Join-Path $root 'app/build.gradle.kts'))) {
    throw 'Abra o terminal na raiz de IPTVPremium (onde estao gradlew e app), ou use -Projeto com o caminho correto.'
}

# Verifica TODOS os arquivos antes de alterar qualquer um.
$pending = @()
foreach ($file in $files) {
    $path = Join-Path $root $file.Path
    if (!(Test-Path -LiteralPath $path -PathType Leaf)) { throw "Arquivo ausente: $($file.Path). Nada foi alterado." }
    $current = Get-TextHash ([IO.File]::ReadAllBytes($path))
    if ($current -eq $file.After) { continue }
    if ($current -ne $file.Before) {
        throw "Arquivo diferente do ZIP IPTVPremium (5): $($file.Path). Nada foi alterado. Esta atualizacao preserva alteracoes posteriores e precisa da mesma versao-base."
    }
    $packed = [IO.MemoryStream]::new([Convert]::FromBase64String($file.Data))
    $gzip = [IO.Compression.GZipStream]::new($packed, [IO.Compression.CompressionMode]::Decompress)
    $plain = [IO.MemoryStream]::new()
    try { $gzip.CopyTo($plain); $bytes = $plain.ToArray() }
    finally { $gzip.Dispose(); $plain.Dispose(); $packed.Dispose() }
    if ((Get-BytesHash $bytes) -ne $file.PayloadHash) { throw 'Falha de integridade no pacote. Nada foi alterado.' }
    $pending += @{ Path = $path; Relative = $file.Path; Bytes = $bytes }
}
if ($pending.Count -eq 0) {
    Write-Host 'Esta atualizacao ja esta aplicada.' -ForegroundColor Green
    return
}

$backup = Join-Path $root ('.navigation-backups/' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
foreach ($file in $pending) {
    $copy = Join-Path $backup $file.Relative
    [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($copy)) | Out-Null
    [IO.File]::Copy($file.Path, $copy, $false)
    if ((Get-FileHash -LiteralPath $file.Path -Algorithm SHA256).Hash -ne (Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash) {
        throw 'Backup nao passou na verificacao. Nenhum arquivo do projeto foi alterado.'
    }
}
try {
    foreach ($file in $pending) { [IO.File]::WriteAllBytes($file.Path, $file.Bytes) }
} catch {
    foreach ($file in $pending) { [IO.File]::Copy((Join-Path $backup $file.Relative), $file.Path, $true) }
    throw
}
Write-Host 'Navegacao atualizada: voltar para categorias, subir para pesquisa e foco direto nas capas visiveis.' -ForegroundColor Green
Write-Host "Backup dos arquivos anteriores: $backup"
Write-Host 'O carregamento/cache das capas foi preservado. Compile e execute pelo Android Studio.'
